import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline


def _pair(v):
    if isinstance(v, (tuple, list)):
        assert len(v) == 2
        return int(v[0]), int(v[1])
    return int(v), int(v)


conv2d_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride_h, int stride_w,
                             int pad_h, int pad_w,
                             int dil_h, int dil_w);
"""

conv2d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ void cp_async4(void* smem_dst, const void* gmem_src,
                                          bool valid) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  const unsigned saddr = (unsigned)__cvta_generic_to_shared(smem_dst);
  const int src_size = valid ? 4 : 0;
  // 4-byte async copy; bytes past src_size are zero-filled, so an
  // out-of-bounds source (src_size == 0) produces a zero in shared memory
  // without touching global memory.
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
               :: "r"(saddr), "l"(gmem_src), "r"(src_size));
#else
  float v = 0.0f;
  if (valid) {
    v = *reinterpret_cast<const float*>(gmem_src);
  }
  *reinterpret_cast<float*>(smem_dst) = v;
#endif
}
__device__ __forceinline__ void cp_async_commit() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
#endif
}
template <typename T,
          int THREADS,
          int OC_TILE,
          int OH_TILE,
          int OW_TILE,
          int OW_REG,
          int IC_CHUNK>
__global__ void conv2d_tiled_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int Hout, int Wout,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int num_ow_tiles,
    int in_h_tile, int in_w_tile)
{
  static_assert(OW_TILE % OW_REG == 0, "OW_TILE must be divisible by OW_REG");
  static_assert(THREADS == OH_TILE * (OW_TILE / OW_REG),
                "THREADS must equal OH_TILE * (OW_TILE / OW_REG)");
  static_assert(OC_TILE % 4 == 0, "OC_TILE must be divisible by 4 for float4 loads");
  static_assert(IC_CHUNK % 2 == 0, "IC_CHUNK must keep smem stages 16B aligned");

  extern __shared__ T smem_raw[];
  // Two-stage shared-memory pipeline: double buffers for the input halo
  // tile and the weight tile so cp.async prefetches overlap with compute.
  const size_t x_stage_elems = (size_t)IC_CHUNK * in_h_tile * in_w_tile;
  const size_t w_stage_elems = (size_t)IC_CHUNK * KH * KW * OC_TILE;
  T* sX_buf0 = smem_raw;
  T* sX_buf1 = smem_raw + x_stage_elems;
  T* sW_buf0 = smem_raw + 2 * x_stage_elems;
  T* sW_buf1 = smem_raw + 2 * x_stage_elems + w_stage_elems;

  const int tid = threadIdx.x;

  const int spatial_tile = blockIdx.x;
  const int oh_tile = spatial_tile / num_ow_tiles;
  const int ow_tile = spatial_tile - oh_tile * num_ow_tiles;

  const int oc_base = blockIdx.y * OC_TILE;
  const int oh0 = oh_tile * OH_TILE;
  const int ow0 = ow_tile * OW_TILE;
  const int n = blockIdx.z;

  constexpr int OW_GROUPS = OW_TILE / OW_REG;
  const int oh_l = tid / OW_GROUPS;
  const int ow_g = tid - oh_l * OW_GROUPS;
  const int oh = oh0 + oh_l;
  const int ow_base = ow0 + ow_g * OW_REG;
  const bool row_active = (oh < Hout);

  const int ih_base = oh0 * stride_h - pad_h;
  const int iw_base = ow0 * stride_w - pad_w;

  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWoc = (int64_t)C * KH * KW;
  const int64_t sWc  = (int64_t)KH * KW;
  const int64_t sWkh = (int64_t)KW;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, _1{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, _1{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, C, KH, KW),
      make_stride(sWoc, sWc, sWkh, _1{})
  );


  float acc[OW_REG][OC_TILE];
  #pragma unroll
  for (int p = 0; p < OW_REG; ++p) {
    #pragma unroll
    for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
      const int oc = oc_base + oc_l;
      float bval = 0.0f;
      if (B != nullptr && oc < OC) {
        bval = (float)B[oc];
      }
      acc[p][oc_l] = bval;
    }
  }

  const int x_tile_elems = IC_CHUNK * in_h_tile * in_w_tile;
  const int w_tile_elems = IC_CHUNK * KH * KW * OC_TILE;
  const int num_ic_chunks = (C + IC_CHUNK - 1) / IC_CHUNK;
  // Two-stage cp.async pipeline: the loader below issues asynchronous
  // global->shared copies (zero-filled when the source element is out of
  // bounds) for one IC chunk and commits them as a single copy group, so
  // prefetching chunk k+1 overlaps with the compute of chunk k.
  auto load_stage = [&](int ic0, T* sXp, T* sWp) {
    // Cooperative predicated load of the input halo tile for IC_CHUNK channels.
    for (int idx = tid; idx < x_tile_elems; idx += THREADS) {
      const int ic_l = idx / (in_h_tile * in_w_tile);
      const int rem  = idx - ic_l * (in_h_tile * in_w_tile);
      const int r    = rem / in_w_tile;
      const int c    = rem - r * in_w_tile;
      const int ic = ic0 + ic_l;
      const int ih = ih_base + r;
      const int iw = iw_base + c;
      const bool valid =
          (ic < C) && ((unsigned)ih < (unsigned)H) && ((unsigned)iw < (unsigned)Win);
      const T* gptr = valid ? &mX(ic, ih, iw) : X;
      cp_async4(&sXp[idx], gptr, valid);
    }
    // Cooperative predicated load of weights: [IC_CHUNK, KH, KW, OC_TILE].
    for (int idx = tid; idx < w_tile_elems; idx += THREADS) {
      const int oc_l = idx % OC_TILE;
      int rem = idx / OC_TILE;
      const int kw = rem % KW;
      rem /= KW;
      const int kh = rem % KH;
      const int ic_l = rem / KH;
      const int oc = oc_base + oc_l;
      const int ic = ic0 + ic_l;
      const bool valid = (oc < OC) && (ic < C);
      const T* gptr = valid ? &mW(oc, ic, kh, kw) : W;
      cp_async4(&sWp[idx], gptr, valid);
    }
    cp_async_commit();
  };
  // Prologue: asynchronously fill stage 0 with the first IC chunk.
  load_stage(0, sX_buf0, sW_buf0);
  for (int chunk = 0; chunk < num_ic_chunks; ++chunk) {
    const int cur = chunk & 1;
    T* sX_ptr = cur ? sX_buf1 : sX_buf0;
    T* sW_ptr = cur ? sW_buf1 : sW_buf0;
    // Prefetch the next IC chunk into the other stage so its global-memory
    // latency overlaps with the compute on the current stage below.
    if (chunk + 1 < num_ic_chunks) {
      const int ic0_next = (chunk + 1) * IC_CHUNK;
      if (cur) {
        load_stage(ic0_next, sX_buf0, sW_buf0);
      } else {
        load_stage(ic0_next, sX_buf1, sW_buf1);
      }
      // At most the just-issued prefetch group may remain in flight, i.e.
      // the copy group feeding the current stage has completed.
      cp_async_wait_group<1>();
    } else {
      cp_async_wait_group<0>();
    }
    __syncthreads();
    Tensor sX = make_tensor(
        make_smem_ptr(sX_ptr),
        make_shape(Int<IC_CHUNK>{}, in_h_tile, in_w_tile),
        make_stride(in_h_tile * in_w_tile, in_w_tile, _1{})
    );
    // Weight tile layout keeps output-channel innermost for unrolled FMAs.
    Tensor sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(Int<IC_CHUNK>{}, KH, KW, Int<OC_TILE>{}),
        make_stride(KH * KW * OC_TILE, KW * OC_TILE, OC_TILE, _1{})
    );
    const int rbase = oh_l * stride_h;
    const int cbase = ow_g * OW_REG * stride_w;
    for (int ic_l = 0; ic_l < IC_CHUNK; ++ic_l) {
      for (int kh = 0; kh < KH; ++kh) {
        const int r = rbase + kh * dil_h;
        for (int kw = 0; kw < KW; ++kw) {
          const int c = cbase + kw * dil_w;
          // Register blocking: load the OC_TILE weights once into
          // registers and reuse them across OW_REG spatial outputs,
          // amortizing shared-memory weight loads over more FMAs.
          float wv[OC_TILE];
          // Vectorized shared-memory loads: the weight tile keeps the
          // OC_TILE output channels innermost and contiguous, and each
          // (ic_l, kh, kw) slice starts at a 16-byte aligned offset, so
          // OC_TILE scalar LDS.32 loads become OC_TILE/4 LDS.128 loads,
          // cutting load-issue pressure in the innermost FMA loop.
          const T* wptr = &sW(ic_l, kh, kw, 0);
          #pragma unroll
          for (int oc4 = 0; oc4 < OC_TILE / 4; ++oc4) {
            const float4 w4 = *reinterpret_cast<const float4*>(wptr + 4 * oc4);
            wv[4 * oc4 + 0] = w4.x;
            wv[4 * oc4 + 1] = w4.y;
            wv[4 * oc4 + 2] = w4.z;
            wv[4 * oc4 + 3] = w4.w;
          }
          #pragma unroll
          for (int p = 0; p < OW_REG; ++p) {
            const float xv = (float)sX(ic_l, r, c + p * stride_w);
            #pragma unroll
            for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
              acc[p][oc_l] += xv * wv[oc_l];
            }
          }
        }
      }
    }
    __syncthreads();
  }

  if (row_active) {
    #pragma unroll
    for (int p = 0; p < OW_REG; ++p) {
      const int ow = ow_base + p;
      if (ow < Wout) {
        #pragma unroll
        for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
          const int oc = oc_base + oc_l;
          if (oc < OC) {
            mY(oc, oh, ow) = (T)acc[p][oc_l];
          }
        }
      }
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride_h, int stride_w,
                             int pad_h, int pad_w,
                             int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) {
    TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  }

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) {
    TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  }

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, KH, KW]");

  const int64_t N  = x.size(0);
  const int64_t C  = x.size(1);
  const int64_t H  = x.size(2);
  const int64_t Win = x.size(3);

  const int64_t OC = w.size(0);
  const int64_t Cw = w.size(1);
  const int64_t KH = w.size(2);
  const int64_t KW = w.size(3);

  TORCH_CHECK(Cw == C, "w.size(1) must equal x.size(1)");
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be positive");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be positive");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be non-negative");

  const int64_t Hout = (H + 2 * pad_h - dil_h * (KH - 1) - 1) / stride_h + 1;
  const int64_t Wout = (Win + 2 * pad_w - dil_w * (KW - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int THREADS  = 128;
  constexpr int OC_TILE  = 16;
  constexpr int OH_TILE  = 8;
  constexpr int OW_TILE  = 64;
  constexpr int OW_REG   = 4;
  constexpr int IC_CHUNK = 2;

  const int in_h_tile = (OH_TILE - 1) * stride_h + (int)(KH - 1) * dil_h + 1;
  const int in_w_tile = (OW_TILE - 1) * stride_w + (int)(KW - 1) * dil_w + 1;

  const int num_ow_tiles = (int)((Wout + OW_TILE - 1) / OW_TILE);
  const int num_oh_tiles = (int)((Hout + OH_TILE - 1) / OH_TILE);

  dim3 block(THREADS);
  dim3 grid(
      (unsigned)(num_oh_tiles * num_ow_tiles),
      (unsigned)((OC + OC_TILE - 1) / OC_TILE),
      (unsigned)N
  );

  const size_t smem_bytes =
      sizeof(float) * 2 * ((size_t)IC_CHUNK * in_h_tile * in_w_tile +
                           (size_t)IC_CHUNK * KH * KW * OC_TILE);

  auto kernel = conv2d_tiled_cute_kernel<float, THREADS, OC_TILE, OH_TILE, OW_TILE, OW_REG, IC_CHUNK>;
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute((const void*)kernel,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
  }

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)OC, (int)Hout, (int)Wout,
      (int)KH, (int)KW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      num_ow_tiles,
      in_h_tile, in_w_tile
  );

  const auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_tiled_ext",
    cpp_sources=conv2d_cpp_decl,
    cuda_sources=conv2d_cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()

        kH, kW = _pair(kernel_size)
        sH, sW = _pair(stride)
        pH, pW = _pair(padding)
        dH, dW = _pair(dilation)

        assert kH > 0 and kW > 0
        assert sH > 0 and sW > 0
        assert pH >= 0 and pW >= 0
        assert dH > 0 and dW > 0

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (kH, kW)
        self.stride = (sH, sW)
        self.padding = (pH, pW)
        self.dilation = (dH, dW)

        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        sH, sW = self.stride
        pH, pW = self.padding
        dH, dW = self.dilation
        return self._ext.conv2d_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else None,
            sH, sW,
            pH, pW,
            dH, dW,
        )

