template <typename T,
          int THREADS,
          int OC_TILE,
          int OH_TILE,
          int OW_TILE,
          int OW_REG,
          int IC_CHUNK>
__global__ void conv2d_tiled_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int OC, int Hout, int Wout,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int num_ow_tiles,
    int in_h_tile, int in_w_tile)
{
  static_assert(OW_TILE % OW_REG == 0, "OW_TILE must be divisible by OW_REG");
  static_assert(THREADS == OH_TILE * (OW_TILE / OW_REG),
                "THREADS must equal OH_TILE * (OW_TILE / OW_REG)");
  static_assert(OC_TILE % 4 == 0, "OC_TILE must be divisible by 4 for float4 loads");
  static_assert(IC_CHUNK % 4 == 0, "IC_CHUNK must keep smem stages 16B aligned");

  extern __shared__ T smem_raw[];
  // Two-stage shared-memory pipeline: double buffers for the input halo
  // tile and the weight tile so cp.async prefetches overlap with compute.
  const size_t x_stage_elems = (size_t)IC_CHUNK * in_h_tile * in_w_tile;
  const size_t w_stage_elems = (size_t)IC_CHUNK * KH * KW * OC_TILE;
  T* sX_buf0 = smem_raw;
  T* sX_buf1 = smem_raw + x_stage_elems;
  T* sW_buf0 = smem_raw + 2 * x_stage_elems;
  T* sW_buf1 = smem_raw + 2 * x_stage_elems + w_stage_elems;

  const int tid = threadIdx.x;

  const int spatial_tile = blockIdx.x;
  const int oh_tile = spatial_tile / num_ow_tiles;
  const int ow_tile = spatial_tile - oh_tile * num_ow_tiles;

  const int oc_base = blockIdx.y * OC_TILE;
  const int oh0 = oh_tile * OH_TILE;
  const int ow0 = ow_tile * OW_TILE;
  const int n = blockIdx.z;

  constexpr int OW_GROUPS = OW_TILE / OW_REG;
  const int oh_l = tid / OW_GROUPS;
  const int ow_g = tid - oh_l * OW_GROUPS;
  const int oh = oh0 + oh_l;
  const int ow_base = ow0 + ow_g * OW_REG;
  const bool row_active = (oh < Hout);

  const int ih_base = oh0 * stride_h - pad_h;
  const int iw_base = ow0 * stride_w - pad_w;

  const int64_t sXn = (int64_t)C * H * Win;
